package main

import (
	"fmt"
	"go/format"
	"image/color"
	"strings"
	"unicode"
)

// How the generated file opens: the line every linter knows generated code by, and what it imports
const sourceOpening = `// Code generated by scripts/tokens from design/tokens.yaml. DO NOT EDIT.

package look

import "image/color"

// The design's colours, each named for what it does, in the order design/tokens.yaml names them
const (
`

// What a constant's name is made of: the type's name, then the token's words, which the file parts with an
// underscore
const (
	constantPrefix = "Colour"
	wordSeparator  = "_"
)

// The themes the generated palette has a case for, by the name of each one's constant
const (
	lightTheme = "ThemeLight"
	darkTheme  = "ThemeDark"
)

// What stands for the terminal's own colour in the generated file
const ownBasicConstant = "BasicOwn"

// How the page's own colour is returned in a theme: the theme's constant, then the colour
const backgroundCase = "\tcase %s:\n\t\treturn %s\n"

// How the palette writes a colour: a literal of image/color's RGBA, its four channels named
const rgbaLayout = "color.RGBA{R: %d, G: %d, B: %d, A: %d}"

// source is the Go of the tokens' colours: a constant for each colour, the palette of each theme, then the page's own
// colour in each theme, which no terminal takes, since it keeps a ground of its own. It is formatted as gofmt would,
// so the file reads as if written by hand.
func source(read tokens) ([]byte, error) {
	palette := paletteOf(read)
	var builder strings.Builder
	builder.WriteString(sourceOpening)
	for index, colour := range palette {
		fmt.Fprintf(&builder, "\t// %s is %s\n", constantName(colour.name), colour.about)
		if index == 0 {
			fmt.Fprintf(&builder, "\t%s Colour = iota\n", constantName(colour.name))
			continue
		}
		fmt.Fprintf(&builder, "\t%s\n", constantName(colour.name))
	}
	builder.WriteString(")\n\n")
	builder.WriteString("// Palette is each of the design's colours as each kind of terminal shows it, in a theme.\n")
	builder.WriteString("func Palette(theme Theme) map[Colour]Shade {\n\tswitch theme {\n")
	writeTheme(&builder, lightTheme, palette, func(shades themedShade) shade { return shades.light })
	writeTheme(&builder, darkTheme, palette, func(shades themedShade) shade { return shades.dark })
	builder.WriteString("\t}\n\treturn nil\n}\n\n")
	fmt.Fprintf(&builder, "// Background is %s\n", read.backgroundAbout)
	builder.WriteString("func Background(theme Theme) color.RGBA {\n\tswitch theme {\n")
	fmt.Fprintf(&builder, backgroundCase, lightTheme, rgbaLiteral(read.background.Light))
	fmt.Fprintf(&builder, backgroundCase, darkTheme, rgbaLiteral(read.background.Dark))
	builder.WriteString("\t}\n\treturn color.RGBA{}\n}\n")
	formatted, err := format.Source([]byte(builder.String()))
	if err != nil {
		return nil, fmt.Errorf("format the generated palette: %w", err)
	}
	return formatted, nil
}

// writeTheme writes the case of one theme: each colour's shade in it.
func writeTheme(builder *strings.Builder, theme string, palette []worked, inTheme func(themedShade) shade) {
	fmt.Fprintf(builder, "\tcase %s:\n\t\treturn map[Colour]Shade{\n", theme)
	for _, colour := range palette {
		chosen := inTheme(colour.shades)
		fmt.Fprintf(builder, "\t\t\t%s: {TrueColour: %s, Indexed: %d, Basic: %s},\n",
			constantName(colour.name), rgbaLiteral(chosen.trueColour), chosen.indexed, basicLiteral(chosen.basic))
	}
	builder.WriteString("\t\t}\n")
}

// constantName is the Go name of a token: on_accent is ColourOnAccent.
func constantName(token string) string {
	var builder strings.Builder
	builder.WriteString(constantPrefix)
	for word := range strings.SplitSeq(token, wordSeparator) {
		letters := []rune(word)
		if len(letters) == 0 {
			continue
		}
		letters[0] = unicode.ToUpper(letters[0])
		builder.WriteString(string(letters))
	}
	return builder.String()
}

// rgbaLiteral is a colour as Go writes it in the palette.
//
//wrapper:names how the palette writes each of its colours
func rgbaLiteral(colour color.RGBA) string {
	return fmt.Sprintf(rgbaLayout, colour.R, colour.G, colour.B, colour.A)
}

func basicLiteral(basic basicValue) string {
	if basic == ownBasic {
		return ownBasicConstant
	}
	return fmt.Sprint(uint8(basic))
}
